import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Matryoshka 表示","description":"","frontmatter":{"title":"Matryoshka 表示","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/matryoshka-embeddings.md","filePath":"llm/matryoshka-embeddings.md","lastUpdated":1789023840000}'),p={name:"llm/matryoshka-embeddings.md"};function _(c,a,u,E,k,f){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="matryoshka-表示" tabindex="-1">Matryoshka 表示 <a class="header-anchor" href="#matryoshka-表示" aria-label="Permalink to &quot;Matryoshka 表示&quot;">​</a></h1><div class="epigraph"><p>同一个向量的前 $k$ 维仍是合法嵌入。短的用于粗检索，长的用于重排，不必为每种维度训一个模型。</p><footer>—— Kusupati 等, Matryoshka Representation Learning</footer></div><p><a href="/llm/hard-negatives">上一课</a>把空间细粒度撑开，默认维数仍是固定的 \\(d\\)。索引内存与 ANN 延迟随 \\(d\\) 涨。本课写 Matryoshka 表示：训练时对前缀维一起做对比损失，使截断仍有意义。缺口是部署预算，不是再挖负例。后课指令嵌入默认你可以先截维再谈「按指令改空间」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>产品常要多层：内存里存 64 维粗向量，命中后再用 768 维精排。若三个模型分别训，空间不对齐，粗召回的 Top-\\(n\\) 对精排无效。Kusupati 等人的 MRL 在同一 \\(z\\in\\mathbb{R}^{d}\\) 上对一组维数 \\(\\{d_1\\lt \\cdots\\lt d\\}\\) 同时施加损失，迫使信息按维数嵌套排列：前几维先编码粗语义，后继维补细节。</p><p>与 PCA 事后截断不同：未经 MRL 训练的向量，能量不一定集中在前缀，截断会毁度量。</p><p><span class="marginnote">嵌套的是<strong>同一塔的输出前缀</strong>，不是一层套一层的网络宽度。实现上是对 \\(z_{1:d_i}\\) 再归一化后做 InfoNCE。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个选定 \\(d_i\\)，取 \\(z^{(i)}=\\mathrm{normalize}(z_{1:d_i})\\)，算 InfoNCE，总损失加权求和。推理：存一份全维向量，按层截断；或索引只存短前缀以省内存。加权不要让最大维独占梯度，否则短前缀学不会。评测必须分列各 \\(d_i\\) 的召回，而不是只报全维。</p>',9)),(e(),n(m,null,{default:r(()=>[h(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%85%A8%E7%BB%B4%20z%22%5D%20--%3E%20P1%5B%22%E5%89%8D%E7%BC%80%20d1%22%5D%0A%20%20Z%20--%3E%20P2%5B%22%E5%89%8D%E7%BC%80%20d2%22%5D%0A%20%20Z%20--%3E%20PF%5B%22%E5%85%A8%E7%BB%B4%20d%22%5D%0A%20%20P1%20--%3E%20L%5B%22%E5%90%84%E7%BB%B4%20InfoNCE%20%E6%B1%82%E5%92%8C%22%5D%0A%20%20P2%20--%3E%20L%0A%20%20PF%20--%3E%20L%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>梯度要求：仅用前 \\(d_1\\) 维也要能分开正负对，于是粗信息被迫挤进前缀。更高维在粗信息已够用的对上可以近零，在细粒度难负例上才有用——与难负例课互补。若难负例全是主题级，高维没有可学的残差，MRL 退化为浪费。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>截断不是免费的：短维上的召回一定弱于全维，只是通常强于另训的小模型或 PCA。下一课指令嵌入改变的是条件，不是维数嵌套。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MRL 让一个向量的前缀维可当合法嵌入，服务粗到细的索引。</li><li>各目标维都要进损失；事后 PCA 不能替代。</li><li>细粒度难负例给高维可学的残差。</li><li>出处：Kusupati 等 <em>Matryoshka Representation Learning</em>。</li></ul>',6))])}const b=i(p,[["render",_]]);export{B as __pageData,b as default};
